import {scalarThreshold} from '../src/scalar-threshold.mjs';

import {facts,equal} from '../src/common.mjs';
function evidenceLedger({observations,entities,requirements=[],rules,epoch,requiredAttributes=['front','back']}) {
  const ids=entities??[...new Set([...observations.map(o=>o.entity),...requirements.map(r=>r.entity)])];
  const ledger={},conflicts=[],missing=[];
  const rows=ids.map(entity=>{
    const f=facts(observations,entity,epoch);
    for (const [attribute,value] of Object.entries(f.values)) ledger[JSON.stringify([entity,attribute])]={value,sources:f.sources[attribute],epoch};
    conflicts.push(...f.conflicts.map(attribute=>({entity,attribute})));
    const needed=[...new Set([...requirements.filter(r=>r.entity===entity).map(r=>r.attribute),...(rules?[...requiredAttributes,...rules.flatMap(r=>Object.keys(r.when))]:[])])];
    const absent=needed.filter(k=>!(k in f.values)); missing.push(...absent.map(attribute=>({entity,attribute})));
    const hits=rules?.filter(r=>Object.entries(r.when).every(([k,v])=>k in f.values && equal(f.values[k],v)));
    return {entity,...f,missing:absent,diagnosis:!rules || f.conflicts.length || absent.length?null:
      hits.length===0?'none':hits.length===1?hits[0].label:null,matchedRuleCount:hits?.length??0,ambiguousRule:(hits?.length??0)>1};
  });
  return {status:rules?(rows.every(r=>r.diagnosis!==null)?'classified':'needs_evidence'):
    missing.length||conflicts.length?'needs_evidence':'ledger_ready',facts:ledger,conflicts,missing,rows,
    reports:rows.filter(r=>r.diagnosis!==null && r.matchedRuleCount===1).map(r=>({entity:r.entity,label:r.diagnosis})),
    note:'Classification is optional and uses only supplied public rules; unsourced values never become facts.'};
}

export default function evidenceDiagnosis(input){return input.mode==='scalar_threshold'?scalarThreshold(input):evidenceLedger(input);}

import {cooperativeForecast} from '../src/cooperative-forecast.mjs';
import {semanticSignal} from '../src/semantic-signals.mjs';
import {resourceContest,consequenceMatrix} from '../src/public-decision-models.mjs';

import {infer,predict,allocations} from '../src/opponent-core.mjs';
import {partition} from '../src/common.mjs';
function nodeModelDecision({base,t,signal,archives=[],history=[],total=14,reverseOdd=false,
  availableArchives=[],budget=0,roundsRemaining=0,objective='guaranteed_win'}) {
  if (!['guaranteed_win','mean_outcome'].includes(objective)) throw Error('Unknown objective');
  const survivors=infer({base,archives,history},reverseOdd);
  if (!survivors.length) return {status:'inconsistent_evidence',survivors};
  const predictions=survivors.map(h=>predict(base,h,t,signal,reverseOdd));
  const ranking=allocations(total).map(action=>{
    const wins=predictions.map(p=>Number(action.filter((v,i)=>v>p[i]).length>=2));
    const scores=predictions.map(p=>Math.sign(action.reduce((n,v,i)=>n+Math.sign(v-p[i]),0)));
    return {action,guaranteedWin:Math.min(...wins),modelWinFraction:wins.reduce((a,b)=>a+b,0)/wins.length,
      mean:scores.reduce((a,b)=>a+b,0)/scores.length,worst:Math.min(...scores)};
  }).sort((a,b)=>objective==='guaranteed_win'?b.guaranteedWin-a.guaranteedWin||b.modelWinFraction-a.modelWinFraction:
    b.mean-a.mean||b.worst-a.worst||Math.max(...a.action)-Math.max(...b.action));
  const archiveRanking=availableArchives.map(q=>({...q,...partition(survivors,q,(h,q)=>predict(base,h,q.t,q.signal,reverseOdd))}))
    .sort((a,b)=>a.worst-b.worst||b.entropy-a.entropy);
  const next=ranking[0].guaranteedWin?null:archiveRanking.find(q=>q.worst<survivors.length && q.cost<=budget-roundsRemaining);
  return {status:next?'inspect_archive':'allocation_ready',survivors,predictions,objective,
    recommendation:ranking[0],ranking:ranking.slice(0,8),archive:next?.id??null,archiveRanking,
    reservedBattleActions:roundsRemaining,guaranteedAcrossSurvivors:Boolean(ranking[0].guaranteedWin),
    note:'Guarantees are conditional on the supplied public 24-hypothesis family. Ranking objective is explicit, not inferred from iteration.'};
}

export default function opponentDecision(input){
 if(input.mode==='cooperative_forecast')return cooperativeForecast(input);
 if(input.mode==='semantic_signal')return semanticSignal(input);
 if(input.mode==='resource_contest')return resourceContest(input);
 if(input.mode==='consequence_matrix')return consequenceMatrix(input);
 return nodeModelDecision(input);
}

import constraintAudit from '../src/constraint-audit.mjs';

import {step,successors,done} from '../src/gate-core.mjs';
import {shortest} from '../src/common.mjs';
import gridPush from '../src/grid-push-plan.mjs';
import permutationPlan from '../src/permutation-plan.mjs';
export default function gateSchedule(input){if(input.mode==='constraint_audit')return constraintAudit(input);if(input.mode==='reversible_permutation')return permutationPlan(input);if(input.mode==='grid_push')return gridPush(input);return gateModel(input);}
function gateModel({config,state={a:0,b:0,pa:0,pb:0},proposed,budget,maxStates=50000}) {
  if (!Number.isInteger(budget)||budget<0) throw Error('Nonnegative integer budget required');
  const plan=shortest(state,s=>successors(config,s),s=>done(config,s),budget,maxStates);
  const validation=proposed?step(config,state,proposed):null;
  const proposedContinuation=validation?.status==='legal' && budget>0?
    shortest(validation.state,s=>successors(config,s),s=>done(config,s),budget-1,maxStates):null;
  let cursor=state;const timeline=[],milestones=[],waits={a:0,b:0};
  for (const [i,action] of (plan.path??[]).entries()) {
    const next=step(config,cursor,action).state;
    if (!action.da) waits.a++;if (!action.db) waits.b++;
    for (const robot of ['a','b']) {
      const field=robot==='a'?'pa':'pb',cargo=robot==='a'?config.aCargo:config.bCargo;
      cargo.forEach((position,bit)=>{if (!(cursor[field]&(1<<bit)) && (next[field]&(1<<bit))) milestones.push({step:i+1,robot,position,cargoIndex:bit});});
    }
    timeline.push({step:i+1,action,before:cursor,after:next});cursor=next;
  }
  const freeMotionLowerBound=Math.max(...['a','b'].map(robot=>{
    const cargo=robot==='a'?config.aCargo:config.bCargo,mask=robot==='a'?state.pa:state.pb;
    const far=Math.max(state[robot],...cargo.filter((_,i)=>!(mask&(1<<i))));return 2*far-state[robot];
  }));
  return {status:plan.status,plan,path:plan.path??null,recommendation:plan.path?.[0]??null,validation,
    proposedContinuation,proposedFitsBudget:proposedContinuation?.status==='planned',timeline,milestones,waits,
    freeMotionLowerBound,synchronizationOverhead:plan.path?plan.path.length-freeMotionLowerBound:null,
    spareActions:plan.path?budget-plan.path.length:null,
    note:'One joint search supplies both the executable route and collection schedule. The free-motion lower bound is not a gate-feasibility proof.'};
}

import {equal} from '../src/common.mjs';
export default function identityOrderJoin({observations,attributes,orders,slotTransform,capacity=2}) {
  if (!Number.isInteger(capacity)||capacity<1) throw Error('Positive capacity required');
  const entries=new Map(),conflicts=[];
  for (const row of observations) {
    if (!row.source || row.visible!==true) continue;
    const old=entries.get(row.id);
    if (old && !equal(old.attributes,row.attributes)) {conflicts.push(row.id);continue;}
    entries.set(row.id,row);
  }
  if (conflicts.length) return {status:'conflicting_memory',ids:conflicts};
  const rows=orders.map((order,index)=>{
    const resolved=Object.create(null),proof=[],missing=[];
    for (const [attribute,q] of Object.entries(order)) {
      if (q===null || typeof q!=='object') {resolved[attribute]=q;continue;}
      const ref=entries.get(q.ref),value=ref && Object.hasOwn(ref.attributes,attribute)?ref.attributes[attribute]:undefined;
      if (value===undefined) {missing.push({ref:q.ref,attribute});continue;}
      if (q.op==='same') resolved[attribute]=value;
      else if (q.op==='opposite' && [1,2].includes(value)) resolved[attribute]=3-value;
      else {missing.push({ref:q.ref,attribute,reason:'unsupported_relation'});continue;}
      proof.push({attribute,reference:q.ref,operation:q.op,observed:value,source:ref.source});
    }
    const candidates=missing.length?[]:[...entries.values()].filter(r=>Object.entries(resolved).every(([k,v])=>equal(r.attributes[k],v)))
      .map(r=>{let slot=r.slot;if(slotTransform){const {slotsPerRoom,shift}=slotTransform;
        if(!Number.isInteger(slotsPerRoom)||slotsPerRoom<1||!Number.isInteger(shift)||!Number.isInteger(slot)) throw Error('Explicit public integer slot transform required');
        slot=((slot+shift)%slotsPerRoom+slotsPerRoom)%slotsPerRoom;}
        return {id:r.id,original:r.id,room:r.room,slot};});
    return {index,resolved,proof,missing,candidates};
  });
  const unique=rows.every(r=>!r.missing.length && r.candidates.length===1),matches=rows.map(r=>r.candidates);
  return {status:unique?'unique_matches':'needs_reference_or_disambiguation',rows,matches,
    incomplete:[...entries.values()].filter(r=>attributes.some(k=>!Object.hasOwn(r.attributes,k))).map(r=>r.id),
    batches:unique?Array.from({length:Math.ceil(rows.length/capacity)},(_,i)=>matches.slice(i*capacity,(i+1)*capacity).flat()):[],
    note:'References use stable original identities; only explicit public slotTransform changes pickup positions. No invented room topology.'};
}

import {rankValue} from '../src/value-decision.mjs';
export default function investmentValue(input){
  const result=rankValue(input),base=result.ranked.find(r=>r.id===input.baselineId);
  return {...result,baselineId:input.baselineId??null,
    comparisons:result.ranked.map(r=>({id:r.id,conservativeValueGain:base?r.utilityLower-base.utilityUpper:null,
      costDifference:base?r.cost-base.cost:null})),
    intent:'Compare investment timing against its public scored benefit and action cost; a feasible expansion is not automatically valuable.'};
}

import {rankValue} from '../src/value-decision.mjs';
export default function reserveTradeoff(input){
  if(!input.reserveSource) return {status:'needs_public_reserve_contract',recommendation:null};
  const result=rankValue(input);
  return {...result,requiredReserves:input.resourceReserve,reserveSource:input.reserveSource,
    resourceSlack:result.ranked.map(r=>{const c=input.candidates.find(c=>c.id===r.id);return {id:r.id,
      slack:Object.fromEntries(Object.entries(input.resourceReserve).map(([k,v])=>[k,c.remainingResources[k].lower-v]))};}),
    intent:'Preserve required future resources, then compare actual scored delivery opportunities; do not maximize unused stock as a proxy goal.'};
}

import {rankValue} from '../src/value-decision.mjs';
export default function goalCommitment(input){
  const result=rankValue(input),best=result.ranked.find(r=>r.id===result.recommendation);
  const terminal=result.ranked.filter(r=>['stop','commit'].includes(r.kind));
  const continuing=result.ranked.filter(r=>!['stop','commit'].includes(r.kind));
  return {...result,decision:best?(terminal.includes(best)?'commit_goal':'continue_with_value'):'acquire_missing_evidence',
    canCommit:!!best&&terminal.includes(best),terminalOptions:terminal.map(r=>r.id),continuationOptions:continuing.map(r=>r.id),
    intent:'Commit only with observed goal evidence; compare stopping against continuing under the public score and remaining action budget.'};
}

import {equal} from '../src/common.mjs';


import {auditExecution} from '../src/execution-ledger.mjs';
import solve from '../src/constraint-solver-diagnostic.mjs';
export default function executionState(input){
  const initial=auditExecution(input);
  if(!initial.safeToWrite)return initial;
  let desired=input.desired??{},diagnostic=null;
  if(input.constraintDiagnostic){
    const q=input.constraintDiagnostic;
    if(q.stage!==input.snapshot.stage||!q.source)return {...initial,status:'needs_current_stage_constraint_source',safeToWrite:false,edits:[]};
    diagnostic=solve({...q,current:input.snapshot.values,fixed:input.fixed??{}});
    if(diagnostic.status!=='unique')return {...initial,status:'no_unique_diagnostic_target',safeToWrite:false,edits:[],diagnostic};
    const conflicts=Object.keys(desired).filter(k=>Object.hasOwn(diagnostic.best.values,k)&&!equal(desired[k],diagnostic.best.values[k]));
    if(conflicts.length)return {...initial,status:'conflicting_desired_state',safeToWrite:false,edits:[],conflicts,diagnostic};
    desired={...diagnostic.best.values,...desired};
  }
  if(Object.keys(desired).length && (!input.desiredSource||input.desiredStage!==input.snapshot.stage) && !diagnostic)
    return {...initial,status:'needs_current_stage_desired_state_source',safeToWrite:false,edits:[]};
  return {...auditExecution({...input,desired}),diagnostic,
    intent:'Track observed effects, confirmed edits and failed actions. Constraint solving may propose a target, but never substitutes for execution evidence.'};
}

import executionState from './executionState.mjs';
import {equal} from '../src/common.mjs';
export default function revisionMemory(input){
  const {activeConstraints,previousConstraints,previousDeductions=[],snapshot}=input;
  const byId=new Map(activeConstraints.map(c=>[c.id,c]));
  if(byId.size!==activeConstraints.length||activeConstraints.some(c=>!c.id||!c.source))
    return {status:'needs_identified_sourced_constraints',safeToWrite:false,edits:[]};
  const changed=previousConstraints.filter(c=>!equal(c,byId.get(c.id))).map(c=>c.id);
  const stageChanged=input.previousSnapshot?.stage!==undefined && input.previousSnapshot.stage!==snapshot?.stage;
  const invalidated=previousDeductions.filter(d=>!d.source||!Array.isArray(d.dependencies)||
    d.dependencies.some(id=>!byId.has(id)||changed.includes(id))||d.stageScoped===true&&d.stage!==snapshot?.stage);

  const invalidIds=new Set(invalidated.map(d=>d.id));
  let changedClosure=true;
  while(changedClosure){changedClosure=false;for(const d of previousDeductions){
    if(!invalidIds.has(d.id)&&(d.deductionDependencies??[]).some(id=>invalidIds.has(id))){invalidIds.add(d.id);invalidated.push(d);changedClosure=true;}
  }}
  const retained=previousDeductions.filter(d=>!invalidIds.has(d.id));
  const result=executionState(input);
  const staleTarget=Object.keys(input.desired??{}).length &&
    (!Array.isArray(input.desiredConstraintSnapshot)||!input.desiredConstraintSnapshot.length||
      input.desiredConstraintSnapshot.some(c=>!equal(c,byId.get(c.id))));
  return {...result,...(staleTarget?{status:'rederive_target_after_revision',safeToWrite:false,edits:[]}:{}),changedConstraintIds:changed,invalidated,retainedDeductions:retained,stageChanged,
    invalidatedValueFields:[...new Set(invalidated.flatMap(d=>d.fields??[]))],
    note:'Stage changes retract unsupported beliefs, not physical cell values. Re-read current state; old derived values never become immutable clues.'};
}

import {facts, cover, equal} from '../src/common.mjs';

export default function evidenceCommit({entity, observations, requirements, epoch,
  views = [], budget, submitCost = 1, maxVisits = 100000}) {
  if (!Number.isFinite(budget) || budget < 0 || !Number.isFinite(submitCost) || submitCost < 0)
    throw Error('Finite nonnegative budget and submitCost required');
  const reqs = Array.isArray(requirements) ? requirements.map(r => [r.attribute,r.value]) : Object.entries(requirements);
  if (reqs.some(([attribute]) => typeof attribute !== 'string') || new Set(reqs.map(r => r[0])).size !== reqs.length)
    throw Error('Requirements must have unique attribute names');
  const audit = facts(observations, entity, epoch), missing = [], contradictions = [];
  for (const [attribute, expected] of reqs) {
    if (!(attribute in audit.values)) missing.push(attribute);
    else if (!equal(audit.values[attribute], expected)) contradictions.push({entity,attribute,expected,
      observed:audit.values[attribute],sources:audit.sources[attribute]});
  }
  const relevant = new Set(reqs.map(r => r[0]));
  const conflicts = audit.conflicts.filter(k => relevant.has(k));
  const reserve = submitCost, canSpend = Math.max(0,budget-reserve);
  const base = {entity,missing,conflicts,contradictions,evidence:audit.sources,reserve,canSpend};

  if (contradictions.length) return {...base,status:'reject_with_witness',decision:'reject_with_evidence',
    witness:contradictions[0],action:{decision:'no',reasonAttribute:contradictions[0].attribute},
    savedUnnecessaryChecks:missing,canCommit:budget>=reserve};
  const needs = [...new Set([...missing,...conflicts])];
  if (!needs.length) return {...base,status:'confirm',decision:'confirm',canCommit:budget>=reserve};
  for (const v of views) if (!Number.isFinite(v.cost) || v.cost < 0 || !Array.isArray(v.covers))
    throw Error('Views require nonnegative cost and explicit public covers');
  const plan = cover(needs,views,canSpend,maxVisits);
  const ranking = views.map(v => ({...v,newAttributes:[...new Set(v.covers.filter(k=>needs.includes(k)))]}))
    .filter(v=>v.cost<=canSpend && v.newAttributes.length)
    .sort((a,b)=>b.newAttributes.length/Math.max(b.cost,1e-9)-a.newAttributes.length/Math.max(a.cost,1e-9));
  return {...base,status:'need_observation',decision:conflicts.length?'resolve_conflict':'acquire_evidence',
    canCommit:false,plan,nextView:plan.chosen?.[0] ?? ranking[0]?.id ?? null,viewRanking:ranking,
    note:'View coverage is a plan, not proof of an unseen value. Commit requires sourced, target-bound evidence.'};
}

import {visualRouteEvidence} from '../src/visual-route-core.mjs';
import explorationRoute from '../src/route-planner.mjs';
import {outcomeMemory} from '../src/outcome-memory-core.mjs';
export default function(input) {
  if(input.mode==='scene_evidence')return visualRouteEvidence(input);
  if(input.mode==='outcome_memory')return outcomeMemory(input);
  if(input.mode!==undefined && input.mode!=='route')throw Error('Use route, outcome_memory or scene_evidence mode');
  return explorationRoute(input);
}

import {codes,feedback,equal,partition} from '../src/common.mjs';
export default function candidateProbe({alphabet,length,archives=[],history=[],proposed,transform='none',
  objective='entropy',maxCandidates=20000,probeLimit=64}){
  if(!['none','rotate','alternate'].includes(transform))throw Error('Unknown public transform');
  if(!['entropy','minimax'].includes(objective))throw Error('Unknown probe objective');
  if(!Number.isInteger(probeLimit)||probeLimit<1)throw Error('Positive probeLimit required');
  const domain=codes(alphabet,length,maxCandidates);if(!domain)return {status:'candidate_limit'};
  let rows=domain.filter(c=>archives.every(r=>equal(feedback(c,r.guess),r.feedback))).map(c=>({initial:c,current:c}));
  let terminal=false;const audit=[];
  for(const [i,r] of history.entries()){
    if(terminal)return {status:'invalid_history',reason:'Action after successful terminal feedback'};
    if(r.index!==i||!r.evidenceId)return {status:'unknown',reason:'Complete ordered sourced history required'};
    rows=rows.filter(c=>equal(feedback(c.current,r.guess),r.feedback));terminal=r.feedback[0]===length;
    const change=terminal?'none':transform==='alternate'?(i%2===0?'rotate':'reverse'):transform;
    audit.push({evidenceId:r.evidenceId,observationIndex:i,survivors:rows.length,transformApplied:change});
    if(change!=='none')rows=rows.map(c=>({...c,current:change==='reverse'?[...c.current].reverse():[...c.current.slice(1),c.current[0]]}));
  }
  if(!rows.length)return {status:'inconsistent_evidence',audit};
  const current=rows.map(r=>r.current),stride=Math.max(1,Math.ceil(current.length/probeLimit));
  const probes=current.filter((_,i)=>i%stride===0);
  if(proposed){if(proposed.length!==length||proposed.some(v=>!alphabet.includes(v)))throw Error('Proposal outside public domain');
    if(!probes.some(p=>equal(p,proposed)))probes.push(proposed);}
  const scores=probes.map(probe=>({probe,...partition(current,probe)}));
  const byEntropy=[...scores].sort((a,b)=>b.entropy-a.entropy||a.expected-b.expected);
  const byMinimax=[...scores].sort((a,b)=>a.worst-b.worst||a.expected-b.expected);
  return {status:terminal?'terminal':current.length===1?'unique_in_complete_domain':'probe',candidateCount:rows.length,
    candidates:current,initialToCurrent:rows.length<=8?rows:undefined,audit,currentWorldIndex:history.length,
    objective,recommendation:terminal?null:(objective==='entropy'?byEntropy:byMinimax)[0],
    bestEntropy:byEntropy[0],bestMinimax:byMinimax[0],original:proposed?scores.find(r=>equal(r.probe,proposed)):null,
    positionDomains:Array.from({length},(_,i)=>[...new Set(current.map(c=>c[i]))]),
    proposalIsPossibleAnswerNow:proposed?current.some(c=>equal(c,proposed)):null,probesEvaluated:scores.length,
    globallyOptimalProbe:false,note:'One candidate history and one feedback partition pass support both ranking objectives. Archives refer to the initial world; transformations occur after nonterminal feedback.'};
}

import {planActorFocus} from '../src/actor-focus.mjs';
import {locateTextScope,auditScopeRequest} from '../src/text-scope.mjs';
import {planAcquisition} from '../src/acquisition-core.mjs';
import {selectDeliveredFrames} from '../src/select-delivered-frames.mjs';
export default function adaptiveAcquisition(input){
  if(input.mode==='plan_actor_focus')return planActorFocus(input);
  if(input.mode==='locate_text_scope')return locateTextScope(input);
  if(input.mode==='audit_scope_request')return auditScopeRequest(input);
  if(input.mode==='select_delivered_frames')return {...selectDeliveredFrames(input),intent:'Budget the inspection of already delivered frames across proposed anchors, separated appearance candidates and temporal context. No new frames or semantic labels are acquired.'};
  return {...planAcquisition(input),intent:'Translate a sourced evidence need into affordable time/frame/region/audio requests using only tools the current host actually offers.'};
}

import {auditCoverage,planAcquisition} from '../src/acquisition-core.mjs';
export default function evidenceCoverage(input){
  const coverage=auditCoverage(input);
  return {...coverage,status:coverage.complete?'coverage_verified':'evidence_gaps',
    acquisition:input.offers&&input.budget!==undefined?planAcquisition(input):null,
    intent:'Audit received temporal coverage, frame density, target detail, legibility and sound; never confuse buying a segment with having sufficient evidence.'};
}

import {planAcquisition} from '../src/acquisition-core.mjs';
export default function gapAcquisition(input){
  const result=planAcquisition(input);
  return {...result,stalledRequirements:result.unsupported.map(r=>r.requirementId),
    intent:'Request missing evidence supplied by the comprehension layer. Suppress identical requests that already failed or added no information; report unresolved gaps rather than infer a hidden transfer.'};
}

import {countRepeatedEvents,requestSequenceAudit} from '../src/repeated-event-ledger.mjs';
import {equal} from '../src/common.mjs';

export default function eventLedger(input){
  if(input.mode==='request_sequence_audit')return requestSequenceAudit(input);
  if(input.mode==='count_repeated_events')return countRepeatedEvents(input);
  return transferLedger(input);
}
function transferLedger({target,initialHolder,events=[],observations=[],endpoint,proposed,coverageComplete=false}) {
  const episodes=aggregateEpisodes({target,initialHolder,observations});
  const derived=episodes.events.map(e=>({id:e.id,target,time:e.end,start:e.start,source:e.sources,type:'handoff',
    from:e.from,to:e.to,releaseObserved:true,receiveObserved:true}));

  events=[...events,...derived];
  let holder=initialHolder,location=null,lastEnd=-Infinity;
  const receipts=[],gaps=[...episodes.incomplete],seen=new Set();
  const ordered=events.filter(e=>e.target===target).sort((a,b)=>a.time-b.time);
  for (const e of ordered) {
    if (!e.id || !e.source || !Number.isFinite(e.time) || seen.has(e.id)) {
      gaps.push({event:e.id??null,reason:'duplicate_or_unsourced_or_untimed_event'}); continue;
    }
    seen.add(e.id);
    if (e.type==='handoff') {
      if (!e.releaseObserved || !e.receiveObserved || e.from!==holder || e.to==null || e.to===holder || (e.start??e.time)<lastEnd) {
        gaps.push({event:e.id,reason:'unproved_handoff'}); continue;
      }
      holder=e.to; location=null;lastEnd=e.time;
      receipts.push({id:e.id,time:e.time,recipient:holder});
    } else if (e.type==='deposit') {
      if (e.actor!==holder || !e.releaseObserved || e.location==null) {
        gaps.push({event:e.id,reason:'unproved_deposit'}); continue;
      }
      location=e.location;
    } else if (e.type==='occlusion') {

      const flags=[e.publicNoExchangeGuarantee,e.noExchangeGuaranteed].filter(v=>v!==undefined);
      if (!flags.length || !flags.every(v=>v===true)) gaps.push({event:e.id,time:e.time,reason:'occlusion'});
    } else gaps.push({event:e.id,reason:'unsupported_event_type'});
  }
  const sequence=receipts.map(r=>r.recipient), answer={count:receipts.length,route:sequence,destination:location};
  const endpointMatches=Boolean(endpoint?.observed===true && endpoint.source && endpoint.target===target &&
    endpoint.holder===holder && equal(endpoint.location,location));
  const canCommit=!gaps.length && location!=null && endpointMatches && coverageComplete===true;
  return {status:canCommit?'audited':'incomplete',holder,location,sequence,count:receipts.length,receipts,
    gaps,uncertain:gaps,episodes,answer,endpointMatches,coverageComplete,canCommit,
    proposalMatches:proposed?equal(proposed,answer):null,
    note:'Repeated recipients count as separate events. A later handoff clears a previous deposit; missing endpoint or coverage proof blocks final commitment.'};
}

function aggregateEpisodes({target, observations}) {
  const groups = new Map(), incomplete = [];
  for (const o of observations) {
    if (o.target !== target) continue;
    if (!o.source || !Number.isFinite(o.time)) { incomplete.push({reason:'unsourced_or_untimed_observation'}); continue; }
    if (!o.episodeId) { incomplete.push({reason: 'missing_episode_identity', source: o.source}); continue; }
    const xs = groups.get(o.episodeId) || []; xs.push(o); groups.set(o.episodeId, xs);
  }
  const events = [];
  for (const [id, rows] of groups) {
    const pairs = new Set(rows.map(r => JSON.stringify([r.from, r.to])));
    const release = rows.filter(r => r.releaseObserved).sort((a, b) => a.time - b.time)[0];
    const receipt = rows.filter(r => r.receiveObserved).sort((a, b) => a.time - b.time).at(-1);
    if (pairs.size !== 1 || !release || !receipt || release.time > receipt.time || rows[0].from === rows[0].to) {
      incomplete.push({episodeId: id, reason: 'unproved_or_conflicting_exchange'}); continue;
    }
    events.push({id, from: rows[0].from, to: rows[0].to, start: release.time, end: receipt.time,
      sources: rows.map(r => r.source)});
  }
  return {events, incomplete};
}
